"""Tests for tasks_api.models — Tag, Task, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTag:
    """Tag construction, normalization, and validation."""

    @pytest.mark.parametrize(
        "raw,expected",
        [
            ("Shopping", "shopping"),
            ("  urgent ", "urgent"),
            ("UPPER", "upper"),
            ("kebab-case", "kebab-case"),
            ("under_score", "under_score"),
            ("a1b2", "a1b2"),
        ],
    )
    def test_normalization(self, raw, expected):
        assert Tag(raw).name == expected

    def test_empty_name_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_max_length_accepted(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    @pytest.mark.parametrize("bad", ["hello world", "a@b", "c!d", "foo.bar"])
    def test_illegal_characters_raise(self, bad):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(bad)

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]


class TestTaskPriority:
    """TaskPriority ordering."""

    def test_order_key_high_is_lowest(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(
            TaskPriority.MEDIUM
        )

    def test_order_key_medium_before_low(self):
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(
            TaskPriority.LOW
        )

    def test_str_enum_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"


class TestTaskStatus:
    def test_str_enum_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"


class TestTaskIsOverdue:
    """Task.is_overdue() logic."""

    def test_no_due_date_not_overdue(self, fixed_now):
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(fixed_now) is False

    def test_done_task_not_overdue(self, fixed_now):
        task = Task(
            id=1,
            title="t",
            status=TaskStatus.DONE,
            due_at=fixed_now - timedelta(days=1),
        )
        assert task.is_overdue(fixed_now) is False

    def test_past_due_pending_is_overdue(self, fixed_now):
        task = Task(id=1, title="t", due_at=fixed_now - timedelta(hours=1))
        assert task.is_overdue(fixed_now) is True

    def test_future_due_pending_not_overdue(self, fixed_now):
        task = Task(id=1, title="t", due_at=fixed_now + timedelta(days=1))
        assert task.is_overdue(fixed_now) is False

    def test_exact_due_at_now_not_overdue(self, fixed_now):
        # due_at == now means NOT overdue (strict < comparison)
        task = Task(id=1, title="t", due_at=fixed_now)
        assert task.is_overdue(fixed_now) is False

